}

/// <returns></returns>
public PointData Timestamp(Instant timestamp, WritePrecision timeUnit)
{
    var time = InstantToBigInteger(timestamp, timeUnit);
    return new PointData(_measurementName,
        timeUnit,
        time,
        _tags,
        _fields);
}

